import asyncio
from playwright.async_api import async_playwright
async def main():
  async with async_playwright() as p:
    b=await p.chromium.launch();errs=[]
    for w,h in [(320,568),(360,640),(390,844),(768,1024),(1280,720)]:
      pg=await b.new_page(viewport={'width':w,'height':h});pg.on('pageerror',lambda e:errs.append(str(e)))
      await pg.goto('http://localhost:8766/');await pg.wait_for_timeout(300)
      for scr,act in [('menu',None),('mine','#mineB'),('comp','#newSong'),('cfg',None),('news','#newsB'),('cal','#calB')]:
        if scr=='cal': await pg.evaluate("()=>document.getElementById('newsOk').click()")
        if act: await pg.click(act);await pg.wait_for_timeout(100)
        if scr=='cfg': await pg.evaluate("()=>{document.getElementById('compBack').click();document.getElementById('mineBack').click();document.getElementById('cfgB').click()}")
        r=await pg.evaluate(f"""()=>{{const s=document.getElementById('{scr}');return [s.scrollHeight>s.clientHeight+1,document.documentElement.scrollWidth>innerWidth]}}""")
        if any(r): print(w,h,scr,'desliza/ancho',r)
      if (w,h)==(320,568): await pg.screenshot(path='tamanos.png')
      # ☁️ cuenta (sin entrar)
      await pg.evaluate("()=>{document.getElementById('calBack').click();document.getElementById('acctB').click()}");await pg.wait_for_timeout(200)
      r=await pg.evaluate("()=>{const s=document.getElementById('acct');return [s.scrollHeight>s.clientHeight+1,document.documentElement.scrollWidth>innerWidth,s.hidden]}")
      if any(r): print(w,h,'acct','desliza/ancho/oculta',r)
      if (w,h)==(320,568): await pg.screenshot(path='pruebas/s_cuenta.png')
      # botón de cuenta del menú: no tapa el título
      await pg.evaluate("()=>{document.getElementById('acctBack').click();document.getElementById('cfgOk').click()}")
      r=await pg.evaluate("()=>{const a=document.getElementById('acctI').getBoundingClientRect(),t=document.querySelector('#menu h1').getBoundingClientRect(),c=document.getElementById('cfgB').getBoundingClientRect();return [a.bottom>t.top&&a.left<t.right&&a.right>t.left,a.left<c.right,document.getElementById('acctI').hidden]}")
      if any(r): print(w,h,'botón de cuenta tapa/oculto',r)
      if (w,h)==(320,568): await pg.screenshot(path='pruebas/s_menu_cuenta.png')
      await pg.evaluate("()=>document.getElementById('cfgB').click()")
      await pg.evaluate("()=>{document.getElementById('acctBack').click()}")
      # 🎨 temas (con Halloween elegido, que tiene más cosas)
      await pg.evaluate("()=>{document.getElementById('temasB').click();document.querySelector('#themeList [data-th=halloween]').click()}");await pg.wait_for_timeout(150)
      r=await pg.evaluate("()=>{const s=document.getElementById('temas');return [s.scrollHeight>s.clientHeight+1,document.documentElement.scrollWidth>innerWidth,s.hidden]}")
      if any(r): print(w,h,'temas','desliza/ancho/oculta',r)
      r=await pg.evaluate("()=>{document.getElementById('temasOk').click();const s=document.getElementById('cfg'),b=document.getElementById('temasB').getBoundingClientRect(),c=document.getElementById('cfgOk').getBoundingClientRect();return [s.scrollHeight>s.clientHeight+1,s.hidden,Math.abs(b.top-c.top)>4]}")
      if any(r): print(w,h,'cfg con temas','desliza/oculta/botones en dos filas',r)
      if (w,h)==(320,568): await pg.screenshot(path='pruebas/s_temas_cfg.png')
      await pg.evaluate("()=>{document.getElementById('temasB').click()}")
      if (w,h)==(320,568): await pg.screenshot(path='pruebas/s_temas.png')
      await pg.evaluate("()=>{document.querySelector('#themeList [data-th=auto]').click();document.getElementById('temasOk').click()}")
      # 🎃 música de Halloween y botón de temas del menú (con Halloween fijo)
      await pg.evaluate("()=>{document.getElementById('cfgOk').click();document.getElementById('temaI').click();document.querySelector('#themeList [data-th=halloween]').click();document.getElementById('temasOk').click()}");await pg.wait_for_timeout(150)
      r=await pg.evaluate("()=>{const m=document.getElementById('menu'),a=document.getElementById('temaI').getBoundingClientRect(),c=document.getElementById('acctI').getBoundingClientRect(),t=document.querySelector('#menu h1').getBoundingClientRect();return [m.scrollHeight>m.clientHeight+1,m.hidden,a.right>c.left-4,a.bottom>t.top]}")
      if any(r): print(w,h,'menú con Halloween','desliza/oculto/temas tapa cuenta/temas tapa título',r)
      if (w,h)==(320,568): await pg.screenshot(path='pruebas/s_menu_hw.png')
      await pg.evaluate("()=>document.getElementById('espB').click()");await pg.wait_for_timeout(150)
      r=await pg.evaluate("()=>{const s=document.getElementById('esp');return [s.scrollHeight>s.clientHeight+1,document.documentElement.scrollWidth>innerWidth,s.hidden]}")
      if any(r): print(w,h,'esp','desliza/ancho/oculta',r)
      if (w,h)==(320,568): await pg.screenshot(path='pruebas/s_esp.png')
      await pg.evaluate("()=>{document.getElementById('espBack').click();document.getElementById('temaI').click();document.querySelector('#themeList [data-th=auto]').click();document.getElementById('temasOk').click();document.getElementById('cfgB').click()}")
      if (w,h)==(360,640):  # captura de las novedades
        await pg.evaluate("()=>{document.getElementById('newsB').click()}");await pg.wait_for_timeout(100)
        await pg.screenshot(path='pruebas/s_news.png')
      # pantallas de una canción: "¿Qué querés tocar?" y 🎙️ Estudio (con una canción de ejemplo del compositor)
      await pg.goto('http://localhost:8766/#prueba');await pg.reload();await pg.wait_for_timeout(300)
      await pg.evaluate("()=>{for(const id of ['calBack','cfgOk'])document.getElementById(id).click()}")
      await pg.click('#mineB');await pg.click('#newSong');await pg.click('#compEx');await pg.click('#compBack');await pg.wait_for_timeout(100)
      await pg.click('#songList [data-p]');await pg.wait_for_timeout(100)
      for scr,act in [('parts',None),('studio','#studioB')]:
        if act: await pg.click(act);await pg.wait_for_timeout(150)
        r=await pg.evaluate(f"""()=>{{const s=document.getElementById('{scr}');return [s.scrollHeight>s.clientHeight+1,document.documentElement.scrollWidth>innerWidth,s.hidden]}}""")
        if any(r): print(w,h,scr,'desliza/ancho/oculta',r)
      if (w,h)==(320,568): await pg.screenshot(path='pruebas/s_estudio.png')
      # resultados (con comparación de desafío) y pantalla de desafío recibido
      await pg.evaluate("()=>{SS.save.name='Sofi';const R={v:1,n:'Sofi',c:'sofi',s:12400,g:'S',a:97,d:1,ln:'',song:{k:'e',i:0},t:[]};SS.startSong(Object.assign(SS.stageSong(0),{reto:R}));for(const n of SS.notes)n.st=1;SS.cnt.p=SS.notes.length;SS.finish(true)}");await pg.wait_for_timeout(1300)
      for scr in ['res']:
        r=await pg.evaluate(f"""()=>{{const s=document.getElementById('{scr}');return [s.scrollHeight>s.clientHeight+1,document.documentElement.scrollWidth>innerWidth,s.hidden]}}""")
        if any(r): print(w,h,scr,'desliza/ancho/oculta',r)
      if (w,h)==(320,568): await pg.screenshot(path='pruebas/s_res.png')
      await pg.evaluate("async()=>{const R=SS.retoFromCur();R.song={k:'f',name:'Una canción larga de prueba',kind:'audio',fp:'x',size:1,dur:200};document.getElementById('res').hidden=true;await SS.openRetoLink(await SS.packReto(R))}");await pg.wait_for_timeout(200)
      r=await pg.evaluate("()=>{const s=document.getElementById('reto');return [s.scrollHeight>s.clientHeight+1,document.documentElement.scrollWidth>innerWidth,s.hidden]}")
      if any(r): print(w,h,'reto','desliza/ancho/oculta',r)
      if (w,h)==(320,568): await pg.screenshot(path='pruebas/s_reto.png')
      # 📜 historial y detalle de un duelo (la partida de recién quedó guardada como duelo)
      await pg.evaluate("async()=>{document.getElementById('reto').hidden=true;await SS.openHist('duels');await new Promise(r=>setTimeout(r,200));const b=document.querySelector('#histList [data-h]');if(b)b.click()}");await pg.wait_for_timeout(300)
      for scr in ['playScr']:
        r=await pg.evaluate(f"""()=>{{const s=document.getElementById('{scr}');return [s.scrollHeight>s.clientHeight+1,document.documentElement.scrollWidth>innerWidth,s.hidden]}}""")
        if any(r): print(w,h,scr,'desliza/ancho/oculta',r)
      if (w,h)==(320,568): await pg.screenshot(path='pruebas/s_duelo.png')
      await pg.evaluate("()=>document.getElementById('plBack').click()");await pg.wait_for_timeout(300)
      r=await pg.evaluate("()=>{const s=document.getElementById('hist');return [s.scrollHeight>s.clientHeight+1,document.documentElement.scrollWidth>innerWidth,s.hidden]}")
      if any(r): print(w,h,'hist','desliza/ancho/oculta',r)
      if (w,h)==(320,568): await pg.screenshot(path='pruebas/s_hist.png')
    print('ok',errs);await b.close()
asyncio.run(main())
